-- RACE TO ZERO for the Solana Breakpoint 2026 badge.
-- A trader runs along the DoubleZero fiber, a shark bites at the cable from below,
-- the public internet fogs the view. Grab all four Edge venue coins to open the DZ tunnel.
-- The badge version of race.speedlab.pro. Art lives in art.lua (generated by tools/art.py).

local A = require("art")

local floor, abs, min, max = math.floor, math.abs, math.min, math.max
local random = math.random

-- ------------------------------------------------------------------ game numbers
-- World units: 1 unit = 2 screen pixels. 60 sim ticks per second, whatever the frame rate.
local U = 2
local TICK_HZ = 60
local STEP_MS = 1000 / TICK_HZ
local MAX_STEPS = 4             -- per frame, so a slow frame does not snowball

local GROUND_Y = 150            -- cable surface in world units
local GY = 176                  -- cable surface on screen
local PLAYER_X, PLAYER_W = 20, 12
local GRAVITY, JUMP_V = 0.19, -3.5
local JUMP_BUFFER = 8           -- a press this many ticks before landing still jumps
local HOLD_GRAVITY = 0.62       -- holding the button while rising: a higher, floatier jump
local HOLD_TICKS = 16           -- for at most this many ticks after take-off
local IBRL_SPEED, IBRL_SCORE = 1.2, 1.2  -- secret IBRL MODE: everything faster, a little more score
local ZERO_SKY_AT = 10000       -- "zero latency" sky once the score passes this

local BASE_SPEED, RAMP_DIST, RAMP_MAX = 1.6, 9000, 0.9
local SPAWN_X, DESPAWN_X = 168, -24
local FIRST_SPAWN_AT, GAP_MIN, GAP_RANGE, TUNNEL_GAP, CLEARANCE = 60, 70, 80, 40, 12
local LATE_START, LATE_SPEED, LATE_OBS, LATE_OBS_MAX = TICK_HZ * 120, 0.35, 0.05, 0.85
local LAP_SPEED, LAP_OBS, LAP_PAIR_P, LAP_PAIR_MAX, PAIR_GAP, PAIR_MAX_H = 0.25, 0.04, 0.15, 0.45, 10, 11
local WORLD_TICKS = 900         -- 15 s per world, 5 worlds = one lap

local DUR = {K = 300, S = 300, H = 480, T = 300, multicast = 300, slow = 120}
local K_SPEED, T_SPEED, SLOW_SPEED, S_SCORE, T_SCORE = 1.6, 2, 0.5, 2, 3
local SCORE_PER_SPEED = 0.045   -- "ms saved" per tick per unit of speed
local SHARK_HIT = 0.5           -- two bites and the cable is cut
local INVULN_HIT, INVULN_ABSORB, CLONES = 70, 50, 3
local HYPURR_BONUS, PIXEL_BONUS, ZERO_BONUS, ZERO_AFTER = 250, 100, 500, TICK_HZ * 60
local GRASS_W = 16
local BIT_SCORE, COMBO_STEP, COMBO_MAX, ARC_P, ROW = 2, 5, 4, 0.55, 5
-- one roll per spawn, cumulative thresholds
local P_OBS, P_GRASS, P_MULTI, P_HYPURR, P_PIXEL, P_BITS = 0.6, 0.64, 0.67, 0.685, 0.7, 0.93
local PREFER_MISSING = 0.8
local PICK_LOW, PICK_HIGH = GROUND_Y - 8, GROUND_Y - 30
local AIRTIME = 2 * -JUMP_V / GRAVITY

local BODY_X0, BODY_X1 = PLAYER_X + 2, PLAYER_X + PLAYER_W - 3
local CENTER_X = PLAYER_X + PLAYER_W / 2
local MISS_X = PLAYER_X - 6

local WORLDS = {
  {obs = {"lag", "jam", "router"}, marks = {"skyline"}},
  {obs = {"candle", "bot", "firewall"}, marks = {"candles"}},
  {obs = {"anchor", "jelly", "bite"}, marks = {"lighthouse", "ship"}},
  {obs = {"merlion", "lag", "packetloss"}, marks = {"mbs", "merlionStatue"}},
  {obs = {"gap", "jam", "firewall"}, marks = {"bigBen"}},
}
-- w, h in world units; h = 2 is a hole in the cable (hits only on the ground)
local OBS = {
  lag = {13, 9}, jam = {10, 12}, candle = {5, 18}, bot = {9, 10}, anchor = {9, 11}, jelly = {8, 10},
  bite = {10, 2}, merlion = {12, 14}, gap = {12, 2}, router = {11, 9}, firewall = {9, 15}, packetloss = {14, 7},
}
local COINS = {"S", "K", "H", "P"}  -- the order the slots fill in
local COIN_INFO = {
  S = {name = "SOLANA", what = "SCORE x2", col = 0x9945FF},
  K = {name = "KALSHI", what = "SPEED UP", col = 0x00D18C},
  H = {name = "HYPERLIQUID", what = "FOG LIFTED", col = 0x97FCE4},
  P = {name = "PHOENIX", what = "SHIELD", col = 0xFF7A45},
}
local PICK_YS = {}
for i = 0, 3 do PICK_YS[i + 1] = PICK_LOW + (PICK_HIGH - PICK_LOW) * i / 3 end
local WAVE = {0, 0.5, 1, 0.5, 0}

-- ------------------------------------------------------------------ images
local IMG, SIZE, NFR = {}, {}, {}
do
  for name, rows in pairs(A.s) do
    local pal = {}
    for k, v in pairs(A.pal) do pal[k] = v end
    if A.p[name] then for k, v in pairs(A.p[name]) do pal[k] = v end end
    IMG[name] = ui.load(rows, {palette = pal})
    SIZE[name] = {#rows[1], #rows}
  end
  for name in pairs(A.s) do
    local base, n = name:match("^(.-)(%d+)$")
    if base and tonumber(n) > (NFR[base] or 0) then NFR[base] = tonumber(n) end
  end
end

local function frame(base, tick, every)
  local n = NFR[base] or 1
  return base .. (floor(tick / every) % n + 1)
end

-- ------------------------------------------------------------------ save, settings, stats
local function int_or(v, lo, hi, def)
  if type(v) ~= "number" or v ~= v or v < lo or v > hi then return def end
  return floor(v)
end

local ACH = {  -- achievements, in the order the stats screen lists them
  {id = "tunnel", name = "FIRST DZ TUNNEL"},
  {id = "lap2", name = "LAP 2"},
  {id = "lap5", name = "LAP 5"},
  {id = "k10", name = "10K CLUB"},
  {id = "clean", name = "A LAP WITHOUT A BITE"},
  {id = "combo", name = "COMBO x5"},
  {id = "hypurr", name = "HYPURR FOUND"},
  {id = "zero", name = "WEN ZERO"},
  {id = "pixel", name = "BROKEN PIXEL"},
  {id = "runs50", name = "50 RUNS"},
  {id = "ibrl", name = "IBRL"},
}

local save = {best = 0, runs = 0, total = 0, tunnels = 0, coins = 0, bits = 0, best_lap = 0, secs = 0, ach = {}}
local settings = {leds = true, name = true}
do
  local v = storage.get("save")
  if type(v) == "table" then
    for _, k in ipairs({"best", "runs", "total", "tunnels", "coins", "bits", "best_lap", "secs"}) do
      save[k] = int_or(v[k], 0, 2000000000, 0)
    end
    if type(v.ach) == "table" then
      for _, a in ipairs(ACH) do if v.ach[a.id] == true then save.ach[a.id] = true end end
    end
  end
  local st = storage.get("settings")
  if type(st) == "table" then
    if st.leds == false then settings.leds = false end
    if st.name == false then settings.name = false end
  end
end
local function persist()
  storage.set("save", save)
end
local function save_settings()
  storage.set("settings", {leds = settings.leds, name = settings.name})
end

-- ------------------------------------------------------------------ LEDs
local has_led = led ~= nil
local led_now = {}
local led_flash, led_flash_col = 0, 0

local function led_put(n, col)
  if not settings.leds then col = 0 end
  if has_led and led_now[n] ~= col then led_now[n] = col led.hex(n, col) end
end
local function leds_off()
  for n = 1, 8 do led_put(n, 0) end
end
local function flash(col, t)
  led_flash, led_flash_col = t or 0.2, col
end

-- ------------------------------------------------------------------ !LAMP rewards
-- Once per UTC day each: 2 for the first DZ tunnel, 3 for reaching lap 2, 2 for a new best.
-- At most 7 a day. The app's award cap on the server is the real limit; this only keeps
-- the app from asking twice.
local LAMP = {tunnel = {2, "first DZ tunnel today"}, lap2 = {3, "lap 2 today"}, best = {2, "new best"}}
local needs_x = false
local lamp_pending, lamp_session = {}, {}

local function today()
  local t = sys.time and sys.time()
  if not t or t < 1700000000 then return nil end  -- no clock yet
  return floor(t / 86400)
end

local function lamp_log()
  local d = today()
  if not d then return nil end
  local log = storage.get("lamps")
  if type(log) ~= "table" or log.day ~= d then log = {day = d, got = {}} end
  if type(log.got) ~= "table" then log.got = {} end
  return log
end

local function award(key)
  if not lamps or not lamps.award or needs_x then return end
  local amount, reason = LAMP[key][1], LAMP[key][2]
  local log = lamp_log()
  local day = log and log.day
  local skey = key .. "@" .. tostring(day)
  if (log and log.got[key]) or lamp_session[skey] or lamp_pending[key] then return end
  lamp_pending[key] = true
  lamps.award(amount, reason, function(ok, r)
    lamp_pending[key] = nil
    if ok and type(r) == "table" and r.needsX then
      needs_x = true
      ui.toast("Link X in My Badge to earn !LAMPs")
      return
    end
    if not ok then return end
    lamp_session[skey] = true
    if type(r) == "table" and (tonumber(r.awarded) or 0) > 0 then
      ui.toast("+" .. floor(r.awarded) .. " !LAMP" .. (r.awarded > 1 and "s" or "") .. "  " .. reason)
    end
    local now = lamp_log()
    if now and now.day == day then
      now.got[key] = true
      storage.set("lamps", now)
    end
  end)
end

-- ------------------------------------------------------------------ leaderboard
-- Our own server; the badge server signs each request, so it knows the badge owner (server/worker.js).
local LB = "https://race-badge-scores.hypnogaba.workers.dev"
local LB_ERR = {
  offline = "Offline: join Wi-Fi to see the board",
  ["not linked"] = "Claim this badge in My Badge first",
  denied = "The board opens once the app is in the store",
  busy = "Badge busy, try again", timeout = "No answer, try again",
  ["too fast"] = "Too fast, wait a moment", unreachable = "Server unreachable",
}

local function lb_name()
  if not settings.name then return "anon" end
  local o = badge and badge.owner and badge.owner()
  return (type(o) == "string" and o ~= "") and o or "anon"
end

local function submit_score(run, cb)
  if not http or run.score <= 0 then return end
  local body = {score = run.score, lap = run.lap, tunnels = run.tunnels, secs = run.secs, name = lb_name()}
  http.post(LB .. "/score", body, function(ok, res)
    if ok and type(res) == "table" and res.status == 200 then
      if cb then cb(true, res) end
      return
    end
    -- no answer or a struggling server: keep the best unsent run for later (a 4xx is final)
    local retry = not ok or type(res) ~= "table" or res.status >= 500 or res.status == 429
    local p = storage.get("lb_pending")
    if retry and (type(p) ~= "table" or (tonumber(p.score) or 0) < run.score) then
      storage.set("lb_pending", body)
    end
    if cb then cb(false, ok and ("server said " .. tostring(type(res) == "table" and res.status)) or res) end
  end)
end

local function flush_pending()
  local p = storage.get("lb_pending")
  if http and type(p) == "table" and type(p.score) == "number" then
    storage.remove("lb_pending")
    submit_score({score = int_or(p.score, 1, 5000000, 0), lap = int_or(p.lap, 1, 999, 1),
      tunnels = int_or(p.tunnels, 0, 9999, 0), secs = int_or(p.secs, 1, 7200, 1)})
  end
end

-- ================================================================== the run (pure game logic)
local S  -- run state

local function new_state()
  return {
    tick = 0, wi = 1, wtick = 0, lap = 0, dist = 0, next_spawn = FIRST_SPAWN_AT, score = 0,
    y = GROUND_Y, vy = 0, shark = 0, combo = 0, invuln = 0, over = false, jump_buf = 0,
    fx = {K = 0, S = 0, H = 0, T = 0, shield = false, multicast = 0, clones = 0, slow = 0},
    got = {}, ngot = 0, last_coin = nil,
    obs = {}, pick = {}, grass = {}, zero_spawned = false,
    stats = {tunnels = 0, coins = 0, bits = 0, hits = 0},
    ev = {},
    air = 0, lap_hits = 0, max_combo = 0, ibrl = false, zero_sky = false,
    got_hypurr = false, got_zero = false, got_pixel = false,
  }
end

local function emit(s, e) s.ev[#s.ev + 1] = e end

local function late_min(s) return max(0, s.tick - LATE_START) / (TICK_HZ * 60) end

local function speed(s)
  local v = BASE_SPEED + min(s.dist / RAMP_DIST, RAMP_MAX) + late_min(s) * LATE_SPEED + s.lap * LAP_SPEED
  local f = s.fx
  if f.K > 0 then v = v * K_SPEED end
  if f.T > 0 then v = v * T_SPEED end
  if f.slow > 0 then v = v * SLOW_SPEED end
  if s.ibrl then v = v * IBRL_SPEED end
  return v
end

local function connected(s)
  local f = s.fx
  return f.K > 0 or f.S > 0 or f.H > 0 or f.T > 0 or f.shield
end

-- -------------------------------------------------- spawning
local function add_pick(s, kind, x, y) s.pick[#s.pick + 1] = {kind = kind, x = x, y = y} end

local function push_pickup(s, kind)
  add_pick(s, kind, SPAWN_X + floor(random() * 16), PICK_YS[random(4)])
end

local function choose_coin(s)
  for _, k in ipairs(COINS) do
    if not s.got[k] then
      if random() < PREFER_MISSING then return k end
      break
    end
  end
  return COINS[random(4)]
end

-- an arc of small coins over an obstacle: hints at the jump and pays for it
local function bit_arc(s, cx)
  for i = 0, ROW - 1 do
    local t = (i - (ROW - 1) / 2) / ((ROW - 1) / 2)
    add_pick(s, "bit", cx + t * 18, GROUND_Y - 12 - 18 * (1 - t * t))
  end
end

-- rows of small coins: flat, wave, steps up, steps down, scatter
local function bit_row(s, x0)
  local kind = random(0, 4)
  local lo, hi = PICK_LOW, PICK_HIGH
  local x = x0
  for i = 0, ROW - 1 do
    local u = i / (ROW - 1)
    local y = lo
    if kind == 1 then y = lo - (lo - hi) * WAVE[i + 1]
    elseif kind == 2 then y = lo - (lo - hi) * u
    elseif kind == 3 then y = hi + (lo - hi) * u
    elseif kind == 4 then y = hi + (lo - hi) * random() end
    add_pick(s, "bit", x, y)
    x = x + (kind == 4 and (7 + random() * 9) or 9)
  end
end

local function add_obs(s, kind, x)
  local sz = OBS[kind]
  s.obs[#s.obs + 1] = {kind = kind, x = x, w = sz[1], h = sz[2]}
end

local function spawn(s)
  local f = s.fx
  if f.T > 0 then
    -- DZ tunnel: no obstacles, only coin showers
    bit_row(s, SPAWN_X)
    s.next_spawn = s.dist + TUNNEL_GAP
    return
  end
  local jump_len = AIRTIME * speed(s) + CLEARANCE
  if not s.zero_spawned and s.tick >= ZERO_AFTER then
    -- gold "00", once per run after the first minute
    s.zero_spawned = true
    add_pick(s, "zero", SPAWN_X, PICK_HIGH + 6)
    s.next_spawn = s.dist + max(GAP_MIN, jump_len)
    return
  end
  local extra = min(LATE_OBS_MAX - P_OBS, late_min(s) * LATE_OBS + s.lap * LAP_OBS)
  local r0 = random()
  local r = r0 - extra
  local pair_w = 0
  if r0 < P_OBS + extra then
    local list = WORLDS[s.wi].obs
    local kind = list[random(#list)]
    local sz = OBS[kind]
    add_obs(s, kind, SPAWN_X)
    local width = sz[1]
    -- from lap 2 some obstacles come in pairs, the second one low; never while grass slows you
    local slow_ahead = f.slow > 0
    for _, g in ipairs(s.grass) do if not g.used then slow_ahead = true end end
    if s.lap > 0 and not slow_ahead and random() < min(LAP_PAIR_MAX, s.lap * LAP_PAIR_P) then
      local low = {}
      for _, k in ipairs(list) do
        if OBS[k][2] > 2 and OBS[k][2] <= PAIR_MAX_H then low[#low + 1] = k end
      end
      if #low > 0 then
        local k2 = low[random(#low)]
        local x2 = SPAWN_X + sz[1] + PAIR_GAP
        add_obs(s, k2, x2)
        width = x2 + OBS[k2][1] - SPAWN_X
      end
    end
    if sz[2] > 2 and random() < ARC_P then bit_arc(s, SPAWN_X + width / 2) end
    pair_w = width - sz[1]
  elseif r < P_GRASS then
    s.grass[#s.grass + 1] = {x = SPAWN_X, w = GRASS_W, used = false}
  elseif r < P_MULTI then
    push_pickup(s, "multicast")
  elseif r < P_HYPURR and f.H > 0 then
    push_pickup(s, "hypurr")  -- the Hyperliquid cat shows up only in the Hyperliquid theme
  elseif r < P_HYPURR then
    push_pickup(s, choose_coin(s))
  elseif r < P_PIXEL then
    push_pickup(s, "brokenPixel")
  elseif r < P_BITS then
    bit_row(s, SPAWN_X)
  else
    push_pickup(s, choose_coin(s))
  end
  local gap = GAP_MIN + random() * GAP_RANGE
  s.next_spawn = s.dist + pair_w + max(gap, jump_len)
end

-- -------------------------------------------------- one tick
local function apply_pickup(s, p)
  local k, f = p.kind, s.fx
  local mult = (f.S > 0 and S_SCORE or 1) * (f.T > 0 and T_SCORE or 1) * (s.ibrl and IBRL_SCORE or 1)
  if k == "bit" then
    s.score = s.score + BIT_SCORE * (1 + min(COMBO_MAX, floor(s.combo / COMBO_STEP))) * mult
    s.combo = s.combo + 1
    if s.combo > s.max_combo then s.max_combo = s.combo end
    s.stats.bits = s.stats.bits + 1
    emit(s, {t = "bit", combo = s.combo})
    return
  elseif k == "hypurr" then
    s.score = s.score + HYPURR_BONUS s.got_hypurr = true emit(s, {t = "rare", kind = k}) return
  elseif k == "zero" then
    s.score = s.score + ZERO_BONUS s.got_zero = true emit(s, {t = "rare", kind = k}) return
  elseif k == "brokenPixel" then
    s.score = s.score + PIXEL_BONUS s.got_pixel = true emit(s, {t = "rare", kind = k}) return
  elseif k == "multicast" then
    f.multicast, f.clones = DUR.multicast, CLONES
    emit(s, {t = "rare", kind = k})
    return
  end
  -- a venue coin
  if k == "P" then f.shield = true else f[k] = DUR[k] end
  s.last_coin = k
  s.stats.coins = s.stats.coins + 1
  if not s.got[k] then s.got[k] = true s.ngot = s.ngot + 1 end
  emit(s, {t = "coin", kind = k})
  if s.ngot == 4 then
    f.T = DUR.T
    s.shark = 0          -- the tunnel forgives a bite
    s.stats.tunnels = s.stats.tunnels + 1
    s.got, s.ngot = {}, 0
    s.obs = {}
    emit(s, {t = "tunnel"})
  end
end

local function hit(s)
  if s.invuln > 0 then return end
  local f = s.fx
  if f.clones > 0 then
    f.clones = f.clones - 1
    s.invuln = INVULN_ABSORB
    emit(s, {t = "absorbed", by = "multicast"})
    return
  end
  if f.shield then
    f.shield = false
    s.invuln = INVULN_ABSORB
    emit(s, {t = "absorbed", by = "shield"})
    return
  end
  s.shark = min(1, s.shark + SHARK_HIT)
  s.stats.hits = s.stats.hits + 1
  s.lap_hits = s.lap_hits + 1
  s.combo = 0
  s.invuln = INVULN_HIT
  emit(s, {t = "hit"})
  if s.shark >= 1 then
    s.over = true
    emit(s, {t = "caught"})
  end
end

-- jump: the button was pressed this tick; held: it is held down now (for a higher jump)
local function step(s, jump, held)
  if s.over then return end
  s.tick = s.tick + 1
  -- worlds and laps
  s.wtick = s.wtick + 1
  if s.wtick >= WORLD_TICKS then
    s.wtick = 0
    s.wi = s.wi % #WORLDS + 1
    emit(s, {t = "world"})
    if s.wi == 1 then
      s.lap = s.lap + 1
      emit(s, {t = "lap", clean = s.lap_hits == 0})
      s.lap_hits = 0
    end
  end
  -- effects run down
  local f = s.fx
  if f.K > 0 then f.K = f.K - 1 end
  if f.S > 0 then f.S = f.S - 1 end
  if f.H > 0 then f.H = f.H - 1 end
  if f.T > 0 then f.T = f.T - 1 end
  if f.slow > 0 then f.slow = f.slow - 1 end
  if f.multicast > 0 then
    f.multicast = f.multicast - 1
    if f.multicast == 0 then f.clones = 0 end
  end
  if s.invuln > 0 then s.invuln = s.invuln - 1 end

  -- jump (a press shortly before landing is kept)
  if jump then s.jump_buf = JUMP_BUFFER end
  if s.jump_buf > 0 then
    if s.y >= GROUND_Y then
      s.vy = JUMP_V
      s.jump_buf = 0
      s.air = 0
      emit(s, {t = "jump"})
    else
      s.jump_buf = s.jump_buf - 1
    end
  end
  s.air = s.air + 1
  s.vy = s.vy + ((held and s.vy < 0 and s.air <= HOLD_TICKS) and GRAVITY * HOLD_GRAVITY or GRAVITY)
  s.y = s.y + s.vy
  if s.y >= GROUND_Y then s.y, s.vy = GROUND_Y, 0 end

  -- the world scrolls
  local v = speed(s)
  s.dist = s.dist + v
  local keep = {}
  for _, o in ipairs(s.obs) do
    o.x = o.x - v
    if o.x + o.w > DESPAWN_X then keep[#keep + 1] = o end
  end
  s.obs = keep
  keep = {}
  for _, p in ipairs(s.pick) do
    if p.kind == "bit" and p.x >= MISS_X and p.x - v < MISS_X then s.combo = 0 end
    p.x = p.x - v
    if p.x > DESPAWN_X then keep[#keep + 1] = p end
  end
  s.pick = keep
  keep = {}
  for _, g in ipairs(s.grass) do
    g.x = g.x - v
    if g.x + g.w > DESPAWN_X then keep[#keep + 1] = g end
  end
  s.grass = keep
  if s.dist >= s.next_spawn then spawn(s) end

  -- pickups
  keep = {}
  for _, p in ipairs(s.pick) do
    if abs(p.x - CENTER_X) < 8 and abs(p.y - (s.y - 7)) < 10 then apply_pickup(s, p)
    else keep[#keep + 1] = p end
  end
  s.pick = keep

  -- grass slows you down
  if s.y >= GROUND_Y then
    for _, g in ipairs(s.grass) do
      if not g.used and BODY_X1 > g.x and BODY_X0 < g.x + g.w then
        g.used = true
        f.slow = DUR.slow
        emit(s, {t = "grass"})
      end
    end
  end

  -- obstacles
  for _, o in ipairs(s.obs) do
    if BODY_X1 > o.x and BODY_X0 < o.x + o.w and s.y > GROUND_Y - o.h + 1 then
      hit(s)
      break
    end
  end
  if s.over then return end
  s.score = s.score + v * SCORE_PER_SPEED * (f.S > 0 and S_SCORE or 1) * (f.T > 0 and T_SCORE or 1)
    * (s.ibrl and IBRL_SCORE or 1)
  if not s.zero_sky and s.score >= ZERO_SKY_AT then
    s.zero_sky = true
    emit(s, {t = "zerosky"})
  end
end

-- the demo autopilot (and the test bot): jump so the trader is in the air over the next obstacle
local demo_err = 0
local function autopilot(s)
  if s.y < GROUND_Y then return false end
  local v = speed(s)
  for _, o in ipairs(s.obs) do
    if o.x + o.w >= BODY_X0 then
      local dist = o.x - BODY_X1
      local ideal = (AIRTIME * v - (o.w + 7)) / 2
      if dist <= ideal + demo_err * v and dist > -o.w then
        demo_err = (random() + random() + random() - 1.5) * 4
        return true
      end
      return false
    end
  end
  return false
end

-- ================================================================== screens
local scene = "title"
local paused = false
local demo = false        -- the autopilot is playing (title screen left idle)
local ibrl = false        -- secret IBRL MODE, entered with a code on the title screen
local V = {}       -- objects of the play screen
local overlay = {}
local acc = 0      -- ms not yet simulated
local jump_req = false
local over_t = 0

local function sx(x) return floor(x * U + 0.5) end
local function sy(y) return GY + floor((y - GROUND_Y) * U + 0.5) end

local function center_label(y, text, size, color)
  local l = ui.label(0, y, text, {size = size, color = color, w = ui.W, align = "center"})
  overlay[#overlay + 1] = l
  return l
end
local function clear_overlay()
  for _, o in ipairs(overlay) do o:remove() end
  overlay = {}
end

-- a pooled image: only talks to the screen when something changed
local function slot(img, scale)
  local o = ui.image(-64, -64, img, {scale = scale or U})
  o:show(false)
  return {obj = o, img = img, x = -64, y = -64, vis = false}
end
local function put(sl, img, x, y)
  if sl.img ~= img then sl.obj:set(img) sl.img = img end
  if sl.x ~= x or sl.y ~= y then sl.obj:pos(x, y) sl.x, sl.y = x, y end
  if not sl.vis then sl.obj:show(true) sl.vis = true end
end
local function hide(sl)
  if sl.vis then sl.obj:show(false) sl.vis = false end
end

-- the scene behind everything: sky, far skyline, a landmark, the cable
local function build_backdrop(wi)
  local W = A.worlds[wi]
  V.sky_col = W.sky
  V.sky = ui.rect(0, 0, ui.W, GY, {color = W.sky})
  V.far = ui.image(0, GY - 112, IMG["far" .. wi], {scale = U})
  V.mark = slot(IMG[WORLDS[wi].marks[1]])
  V.mark_x, V.mark_i = ui.W + 20, 1
  V.earth = ui.rect(0, GY, ui.W, ui.H - GY, {color = W.earth})
  V.cable = ui.rect(0, GY, ui.W, 3, {color = 0x3FF5E0})
  V.cable_col = 0x3FF5E0
  V.pulses = {}
  for i = 1, 5 do V.pulses[i] = ui.rect(i * 64, GY + 1, 10, 1, {color = 0xCFEFFF}) end
end

local function set_world_backdrop(wi)
  local W = A.worlds[wi]
  V.far:set(IMG["far" .. wi])
  V.earth:color(W.earth)
  V.mark_i = 1
end

local function build_play()
  ui.clear()
  ui.bg(0x000000)
  V = {}
  overlay = {}
  build_backdrop(1)
  V.grass = {slot(IMG.grass1), slot(IMG.grass1)}
  V.obs = {}
  for i = 1, 6 do V.obs[i] = slot(IMG.lag1) end
  V.pick = {}
  for i = 1, 26 do V.pick[i] = slot(IMG.bit1) end
  V.shark = slot(IMG.shark1)
  V.clones = {slot(IMG.traderRun1), slot(IMG.traderRun1), slot(IMG.traderRun1)}
  V.player = slot(IMG.traderRun1)
  V.shield = slot(IMG.shield1)
  V.fog = slot(IMG.fog)
  -- HUD
  V.score = ui.label(6, 2, "0", {size = 20, color = 0xFFD166})
  V.unit = ui.label(6, 24, "ms saved", {size = 12, color = "dim"})
  V.where = ui.label(6, 38, "", {size = 12, color = "dim"})
  V.sharkicon = ui.image(122, 6, IMG.shark1, {scale = 1})
  V.pips = {ui.rect(142, 8, 6, 8, {color = 0x333344}), ui.rect(150, 8, 6, 8, {color = 0x333344})}
  V.slots = {}
  for i, k in ipairs(COINS) do
    V.slots[i] = slot(IMG["slot" .. k])
    put(V.slots[i], IMG["slot" .. k], 214 + (i - 1) * 25, 3)
  end
  V.banner = ui.label(0, 58, "", {size = 20, color = "text", w = ui.W, align = "center"})
  V.banner2 = ui.label(0, 82, "", {size = 12, color = "dim", w = ui.W, align = "center"})
  V.banner_t = 0
  V.pops = {}
  for i = 1, 3 do
    V.pops[i] = {l = ui.label(-200, -200, "", {size = 12, color = "text"}), t = 0}
  end
  V.hud_t = 0
  V.where_text = ""
  V.score_text = ""
  V.slot_state = {}
  V.pip_state = {}
  V.theme = nil
  V.wi = 1
  V.lunge = 0
end

local function banner(text, sub, color, t)
  V.banner:text(text)
  V.banner:color(color or "text")
  V.banner2:text(sub or "")
  V.banner_t = t or 1.6
end

local function popup(text, x, y, color)
  local best, slot_n = 1e9, 1
  for i, p in ipairs(V.pops) do
    if p.t < best then best, slot_n = p.t, i end
  end
  local p = V.pops[slot_n]
  p.t, p.x, p.y = 0.9, x, y
  p.l:text(text)
  p.l:color(color or "text")
  p.l:pos(floor(x), floor(y))
end

local WORLD_NAME = {}
for i, w in ipairs(A.worlds) do WORLD_NAME[i] = w.name end

local function theme_of(s)
  local f = s.fx
  if f.T > 0 then return "T" end
  if V.zero_t and V.zero_t > 0 then return "Z" end
  local k = s.last_coin
  if k == "P" and f.shield then return "P" end
  if k and k ~= "P" and f[k] > 0 then return k end
  return nil
end

-- -------------------------------------------------- achievements
local function unlock(id, s)
  if demo or save.ach[id] then return end
  save.ach[id] = true
  V.ach_dirty = true
  for _, a in ipairs(ACH) do
    if a.id == id then
      popup("UNLOCKED: " .. a.name, 40, 120, 0x14F195)
      flash(0x14F195, 0.3)
    end
  end
end

-- -------------------------------------------------- events -> screen, LEDs
local function handle_events(s)
  for _, e in ipairs(s.ev) do
    local t = e.t
    if t == "coin" then
      local c = COIN_INFO[e.kind]
      popup(c.name, sx(PLAYER_X) + 20, sy(s.y) - 44, c.col)
      if s.fx.T <= 0 then banner(c.what, c.name .. "  " .. s.ngot .. "/4 TO THE DZ TUNNEL", c.col, 1.2) end
      flash(c.col, 0.15)
    elseif t == "tunnel" then
      banner("DZ TUNNEL", "ZERO LATENCY. SCORE x3", 0x14F195, 2.2)
      flash(0x14F195, 0.4)
      unlock("tunnel", s)
      if not demo then award("tunnel") end
    elseif t == "hit" then
      V.lunge = 0.5
      if s.shark < 1 then banner("SHARK BITE!", "ONE MORE HIT CUTS THE CABLE", 0xFF3D6E, 1.6) end
      flash(0xFF0000, 0.5)
    elseif t == "absorbed" then
      popup(e.by == "shield" and "SHIELD SAVED YOU" or "A CLONE TOOK IT", sx(PLAYER_X), sy(s.y) - 44, 0xFF7A45)
      flash(0xFF7A45, 0.2)
    elseif t == "world" then
      banner("WORLD 0" .. s.wi .. "  " .. WORLD_NAME[s.wi], nil, "text", 1.6)
    elseif t == "lap" then
      banner("LAP " .. (s.lap + 1), "FASTER. DENSER. KEEP RUNNING", 0xFFD166, 2)
      flash(0xFFD166, 0.3)
      if s.lap + 1 >= 2 then unlock("lap2", s) if not demo then award("lap2") end end
      if s.lap + 1 >= 5 then unlock("lap5", s) end
      if e.clean then unlock("clean", s) end
    elseif t == "zerosky" then
      V.zero_t = 5
      banner("ZERO LATENCY", "10 000 ms SAVED. THE SKY IS YOURS", 0xFFD166, 2.5)
      flash(0xFFD166, 0.5)
      unlock("k10", s)
    elseif t == "grass" then
      popup("TOUCHED GRASS: SLOW", sx(PLAYER_X), sy(s.y) - 44, 0x2ECC71)
    elseif t == "rare" then
      local txt = ({hypurr = "+250 HYPURR", zero = "+500 WEN ZERO", brokenPixel = "+100 BROKEN PIXEL",
        multicast = "MULTICAST x3"})[e.kind]
      popup(txt, sx(PLAYER_X) + 10, sy(s.y) - 44, 0xFFD166)
      flash(0xFFD166, 0.2)
      if e.kind == "hypurr" or e.kind == "zero" or e.kind == "brokenPixel" then
        unlock(e.kind == "brokenPixel" and "pixel" or e.kind, s)
      end
    elseif t == "bit" then
      if e.combo % COMBO_STEP == 0 and e.combo <= COMBO_STEP * COMBO_MAX then
        popup("x" .. (1 + floor(e.combo / COMBO_STEP)), sx(PLAYER_X) + 26, sy(s.y) - 36, 0xFFD166)
        if e.combo >= COMBO_STEP * COMBO_MAX then unlock("combo", s) end
      end
    end
  end
  s.ev = {}
end

local function update_leds(s, dt)
  if led_flash > 0 then
    led_flash = led_flash - dt
    for n = 1, 8 do led_put(n, led_flash_col) end
    return
  end
  for i, k in ipairs(COINS) do led_put(i, s.got[k] and COIN_INFO[k].col or 0) end
  led_put(5, s.shark >= 0.5 and 0xFF0000 or 0)
  led_put(6, s.shark >= 0.5 and 0xFF0000 or 0)
  local th = theme_of(s)
  local c = 0
  if th == "T" then
    c = (floor(s.tick / 6) % 2 == 0) and 0x14F195 or 0x9945FF
  elseif th == "Z" then
    c = 0xFFD166
  elseif th then
    c = COIN_INFO[th].col
  end
  led_put(7, c)
  led_put(8, c)
end

-- -------------------------------------------------- drawing a frame
local function draw(s, dt)
  -- world change: new skyline
  if V.wi ~= s.wi then V.wi = s.wi set_world_backdrop(s.wi) end
  -- sky tint for venue bonuses and the tunnel
  local th = theme_of(s)
  if th ~= V.theme then
    V.theme = th
    V.sky:color(th and A.themes[th] or A.worlds[s.wi].sky)
    local cc = th == "T" and 0x14F195 or th == "Z" and 0xFFD166 or th and COIN_INFO[th].col or 0x3FF5E0
    V.cable:color(cc)
  elseif not th and V.sky_world ~= s.wi then
    V.sky:color(A.worlds[s.wi].sky)
  end
  V.sky_world = s.wi

  local v = speed(s)
  -- landmark drifts slowly (parallax)
  local mk = WORLDS[s.wi].marks
  V.mark_x = V.mark_x - v * U * 0.35 * (dt * TICK_HZ)
  local mname = mk[(V.mark_i - 1) % #mk + 1]
  local mw = SIZE[mname][1] * U
  if V.mark_x < -mw then
    V.mark_x = ui.W + random(20, 140)
    V.mark_i = V.mark_i + 1
    mname = mk[(V.mark_i - 1) % #mk + 1]
  end
  put(V.mark, IMG[mname], floor(V.mark_x), GY - SIZE[mname][2] * U)
  -- light pulses running along the cable
  local off = floor(s.dist * U) % 64
  for i, p in ipairs(V.pulses) do p:pos((i - 1) * 64 - off + 64, GY + 1) end

  -- grass
  for i, sl in ipairs(V.grass) do
    local g = s.grass[i]
    if g then put(sl, IMG.grass1, sx(g.x), GY - 6) else hide(sl) end
  end
  -- obstacles
  for i, sl in ipairs(V.obs) do
    local o = s.obs[i]
    if o then
      local name = frame(o.kind, s.tick, 15)
      local y = o.h <= 2 and (GY - U) or (GY - SIZE[name][2] * U)
      put(sl, IMG[name], sx(o.x), y)
    else
      hide(sl)
    end
  end
  -- pickups
  local bitf = {"bit1", "bit2", "bit3", "bit2"}
  for i, sl in ipairs(V.pick) do
    local p = s.pick[i]
    if p and p.x < 164 then
      local name
      if p.kind == "bit" then name = bitf[floor(s.tick / 8) % 4 + 1]
      elseif #p.kind == 1 then name = "coin" .. p.kind
      elseif p.kind == "hypurr" then name = frame("hypurr", s.tick, 10)
      elseif p.kind == "multicast" then name = "multicast1"
      elseif p.kind == "brokenPixel" then name = "brokenPixel1"
      else name = "zero1" end
      local w, h = SIZE[name][1] * U, SIZE[name][2] * U
      put(sl, IMG[name], sx(p.x) - floor(w / 2), sy(p.y) - floor(h / 2))
    else
      hide(sl)
    end
  end

  -- the trader
  local py = sy(s.y) - 14 * U
  local px = sx(PLAYER_X)
  local pname = s.y < GROUND_Y and "traderJump1" or frame("traderRun", floor(s.dist), 9)
  if s.fx.H > 0 then
    -- Hyperliquid: the trader becomes Hypurr (only the picture changes, the hitbox stays)
    pname = frame("hypurr", floor(s.dist), 9)
    py = sy(s.y) - 10 * U
  end
  if s.invuln > 0 and floor(s.invuln / 4) % 2 == 0 and not s.over then
    hide(V.player)
  else
    put(V.player, IMG[pname], px, py)
  end
  for i, sl in ipairs(V.clones) do
    if s.fx.clones >= i then put(sl, IMG[pname], px - i * 9, py + (i % 2) * 2) else hide(sl) end
  end
  if s.fx.shield then
    put(V.shield, IMG[frame("shield", s.tick, 6)], px + 12 - 22, py + 14 - 22)
  else
    hide(V.shield)
  end
  -- the shark under the cable: closer with every bite, lunges when it bites
  if V.lunge > 0 then V.lunge = V.lunge - dt end
  local shx = -6 + floor(s.shark * 52) + (V.lunge > 0 and 14 or 0) + floor(math.sin(s.tick / 20) * 3)
  local shy = GY + 12 + (V.lunge > 0 and -4 or 0)
  put(V.shark, IMG[frame("shark", s.tick, 10)], shx, shy)

  -- fog of the public internet, unless a venue connects you to DZ
  if connected(s) then hide(V.fog) else put(V.fog, IMG.fog, ui.W - 80, GY - 154) end

  if V.zero_t and V.zero_t > 0 then V.zero_t = V.zero_t - dt end
  -- banner and popups
  if V.banner_t > 0 then
    V.banner_t = V.banner_t - dt
    if V.banner_t <= 0 then V.banner:text("") V.banner2:text("") end
  end
  for _, p in ipairs(V.pops) do
    if p.t > 0 then
      p.t = p.t - dt
      p.y = p.y - dt * 30
      if p.t <= 0 then p.l:pos(-200, -200) else p.l:pos(floor(p.x), floor(p.y)) end
    end
  end

  -- HUD, ten times a second
  V.hud_t = V.hud_t - dt
  if V.hud_t <= 0 then
    V.hud_t = 0.1
    local st = tostring(floor(s.score))
    if st ~= V.score_text then V.score_text = st V.score:text(st) end
    local wt = "LAP " .. (s.lap + 1) .. "  " .. WORLD_NAME[s.wi]
    if s.fx.T > 0 then wt = "DZ TUNNEL " .. (floor(s.fx.T / TICK_HZ) + 1) .. "s" end
    if wt ~= V.where_text then V.where_text = wt V.where:text(wt) end
    for i, k in ipairs(COINS) do
      local on = s.got[k] and true or false
      if V.slot_state[i] ~= on then
        V.slot_state[i] = on
        put(V.slots[i], IMG[(on and "coin" or "slot") .. k], 214 + (i - 1) * 25, 3)
      end
    end
    local bites = floor(s.shark / SHARK_HIT + 0.01)
    for i = 1, 2 do
      local on = bites >= i
      if V.pip_state[i] ~= on then
        V.pip_state[i] = on
        V.pips[i]:color(on and 0xFF3D6E or 0x333344)
      end
    end
  end
end

-- ================================================================== scenes
local show_title, show_help, show_over, show_lb, show_stats, show_settings, show_share
local last_run = nil   -- {score, lap, tunnels, secs, new_best} of the last finished run
local lb_back = "title"

local function held()
  if not sys.keys then return true end
  local k = sys.keys()
  return type(k) == "table" and (k.up or k.select) and true or false
end

local function start_run(is_demo)
  scene = "play"
  demo = is_demo and true or false
  paused = false
  acc = 0
  jump_req = false
  S = new_state()
  S.ibrl = ibrl and not demo
  build_play()
  if demo then
    ui.label(0, 22, "DEMO  -  PRESS ANY KEY TO PLAY", {size = 12, color = 0x3FF5E0, w = ui.W, align = "center"})
    ui.hint("any key: menu")
    return
  end
  if S.ibrl then
    unlock("ibrl", S)
    banner("IBRL MODE", "INCREASE BANDWIDTH, REDUCE LATENCY", 0xFFD166, 2)
  elseif save.runs < 2 then
    banner("UP or SELECT = JUMP", "HOLD FOR HIGHER. GRAB S K H P", "text", 3.5)
  else
    banner("WORLD 01  CITY", "OUTRUN THE SHARK", "text", 1.4)
  end
  ui.hint("UP / SELECT jump (hold: higher)    CANCEL pause")
end

local function set_pause(on)
  paused = on
  if on then
    -- a banner would show through the pause band
    V.banner:text("") V.banner2:text("") V.banner_t = 0
    overlay[#overlay + 1] = ui.rect(0, 70, ui.W, 74, {color = 0x0B1030})
    overlay[#overlay + 1] = ui.gradient(0, 70, ui.W, 3)
    overlay[#overlay + 1] = ui.gradient(0, 141, ui.W, 3)
    center_label(82, "PAUSED", 32, "text")
    center_label(120, "SELECT resume    CANCEL quit to menu", 12, "dim")
    leds_off()
  else
    clear_overlay()
  end
end

-- stats, best, achievements, !LAMPs and the board, once per real run
local function finish_run()
  local s = S
  local run = {score = floor(s.score), lap = s.lap + 1, tunnels = s.stats.tunnels,
    secs = max(1, floor(s.tick / TICK_HZ + 0.5)), new_best = false}
  save.runs = save.runs + 1
  save.total = min(2000000000, save.total + run.score)
  save.tunnels = save.tunnels + s.stats.tunnels
  save.coins = save.coins + s.stats.coins
  save.bits = save.bits + s.stats.bits
  save.secs = save.secs + run.secs
  if run.lap > save.best_lap then save.best_lap = run.lap end
  if run.score > save.best then
    save.best = run.score
    run.new_best = save.runs > 1
  end
  if save.runs >= 50 then save.ach.runs50 = true end
  persist()
  if run.new_best then award("best") end
  last_run = run
  return run
end

show_over = function()
  scene = "over"
  over_t = 0.6
  local run = finish_run()
  overlay[#overlay + 1] = ui.rect(0, 40, ui.W, 140, {color = 0x0B1030})
  overlay[#overlay + 1] = ui.gradient(0, 40, ui.W, 3)
  overlay[#overlay + 1] = ui.gradient(0, 177, ui.W, 3)
  center_label(48, "THE SHARK CUT THE CABLE", 20, 0xFF3D6E)
  center_label(74, run.score .. " ms saved", 32, 0xFFD166)
  center_label(110, run.new_best and "NEW BEST!" or ("BEST " .. save.best), 14, run.new_best and 0x14F195 or "dim")
  center_label(128, "lap " .. run.lap .. "   tunnels " .. run.tunnels .. "   coins " .. S.stats.coins
    .. "   bits " .. S.stats.bits, 12, "dim")
  local rank = center_label(146, http and "sending to the board..." or "", 12, 0x3FF5E0)
  center_label(162, "UP share on X    DOWN leaderboard", 12, "text")
  ui.hint("SELECT run again    CANCEL menu")
  submit_score(run, function(ok, res)
    if scene ~= "over" then return end
    local data = ok and json.decode(res.body)
    if type(data) == "table" and type(data.me) == "table" then
      rank:text("YOU ARE #" .. int_or(data.me.r, 1, 999999, 0) .. " OF ALL TIME")
    else
      rank:text(ok and "" or ("not sent: " .. tostring(LB_ERR[res] or res)))
    end
  end)
end

-- ------------------------------------------------------------------ share on X (a QR the phone scans)
local function urlenc(s)
  return (s:gsub("[^%w%-%._~]", function(c)
    if c == " " then return "+" end
    return string.format("%%%02X", string.byte(c))
  end))
end

show_share = function()
  scene = "share"
  ui.clear()
  ui.bg(0x0B1030)
  local r = last_run or {score = save.best, lap = save.best_lap, tunnels = 0}
  local text = "I saved " .. r.score .. " ms on the DoubleZero fiber in Race to Zero on my Breakpoint badge."
    .. " Lap " .. r.lap .. ", outran the shark. @doublezero @SolanaFndn race.speedlab.pro"
  local url = "https://x.com/intent/post?text=" .. urlenc(text)
  ui.label(8, 10, "SHARE", {size = 20, color = "text"})
  ui.label(8, 40, "Scan with", {size = 12, color = "dim"})
  ui.label(8, 54, "your phone:", {size = 12, color = "dim"})
  ui.label(8, 68, "X opens with", {size = 12, color = "dim"})
  ui.label(8, 82, "the post ready.", {size = 12, color = "dim"})
  ui.label(8, 110, r.score .. " ms", {size = 20, color = 0xFFD166})
  ui.label(8, 136, "lap " .. r.lap, {size = 12, color = "dim"})
  if ui.qr then
    local ok = pcall(ui.qr, 112, 6, 204, url)
    if not ok then ui.label(112, 100, "QR too long", {size = 12, color = "pink"}) end
  else
    ui.label(112, 90, "Update Solana OS", {size = 14, color = "pink"})
    ui.label(112, 110, "to show the QR", {size = 14, color = "pink"})
  end
  ui.hint("SELECT or CANCEL back")
end

-- ------------------------------------------------------------------ leaderboard screen
local lb = {when = "all", gen = 0}

local function lb_show(ok, res, gen)
  if scene ~= "lb" or gen ~= lb.gen then return end
  if not ok then lb.status:text(LB_ERR[res] or ("Error: " .. tostring(res))) return end
  local data = type(res) == "table" and res.status == 200 and json.decode(res.body)
  if type(data) ~= "table" or type(data.top) ~= "table" then
    lb.status:text("Server said " .. tostring(type(res) == "table" and res.status))
    return
  end
  lb.status:text(#data.top == 0 and (lb.when == "today" and "No runs today. Be the first!" or "No runs yet. Be the first!") or "")
  for n = 1, 10 do
    local r = data.top[n]
    if type(r) == "table" then
      lb.rows[n]:text(string.format("%2d %-16s %8d  L%d", int_or(r.r, 1, 999999, n),
        tostring(r.n):sub(1, 16), int_or(r.s, 0, 5000000, 0), int_or(r.l, 1, 999, 1)))
    else
      lb.rows[n]:text("")
    end
  end
  if type(data.me) == "table" then
    lb.me:text("YOU  #" .. int_or(data.me.r, 1, 999999, 0) .. "   " .. int_or(data.me.s, 0, 5000000, 0) .. " ms")
  else
    lb.me:text(lb.when == "today" and "Run today to get on this board" or "Finish a run to get on the board")
  end
end

local function lb_fetch()
  lb.gen = lb.gen + 1
  local gen = lb.gen
  lb.tab:text(lb.when == "all" and "< ALL TIME >  today" or "  all time  < TODAY >")
  for n = 1, 10 do lb.rows[n]:text("") end
  lb.me:text("")
  lb.status:text("Loading...")
  if not http then lb.status:text("This badge has no http yet") return end
  http.get(LB .. "/top?n=10&when=" .. lb.when, function(ok, res) lb_show(ok, res, gen) end)
end

